import{_ as a,c as o,a2 as n,o as t}from"./chunks/framework.CO0qOYmW.js";const m=JSON.parse('{"title":"HarmonyOS","description":"","frontmatter":{},"headers":[],"relativePath":"crossend/03-harmonyOs/index.md","filePath":"crossend/03-harmonyOs/index.md","lastUpdated":1764081321000}'),e={name:"crossend/03-harmonyOs/index.md"};function l(i,r,s,h,d,c){return t(),o("div",null,r[0]||(r[0]=[n('<h1 id="harmonyos" tabindex="-1">HarmonyOS <a class="header-anchor" href="#harmonyos" aria-label="Permalink to &quot;HarmonyOS&quot;">​</a></h1><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><h2 id="核心优势" tabindex="-1">核心优势 <a class="header-anchor" href="#核心优势" aria-label="Permalink to &quot;核心优势&quot;">​</a></h2><p>HarmonyOS（鸿蒙系统）是华为开发的一款面向全场景的分布式操作系统，具有以下核心优势：</p><ul><li><strong>分布式架构</strong>：基于分布式软总线、分布式数据管理和分布式任务调度，实现设备间的无缝协作</li><li><strong>微内核设计</strong>：采用微内核架构，提供更高的安全性和可靠性</li><li><strong>跨设备协同</strong>：支持多种设备间的互联互通和协同工作</li><li><strong>统一开发平台</strong>：使用方舟开发框架（ArkUI），支持多种开发语言和范式</li><li><strong>一次开发，多端部署</strong>：同一套代码可适配多种设备形态</li></ul><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>HarmonyOS 适用于以下场景：</p><ul><li><strong>智能手机和平板电脑</strong>：提供流畅的用户体验和丰富的应用生态</li><li><strong>智能穿戴设备</strong>：如智能手表、智能手环等，提供健康监测和生活便利功能</li><li><strong>智能家居设备</strong>：如智能电视、智能冰箱、智能灯泡等，实现智能家居的互联互通</li><li><strong>智能车载系统</strong>：提供导航、娱乐和车辆控制等功能</li><li><strong>工业设备</strong>：支持工业场景的智能化和数字化转型</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p>HarmonyOS 支持多种开发语言和技术栈：</p><h3 id="开发语言" tabindex="-1">开发语言 <a class="header-anchor" href="#开发语言" aria-label="Permalink to &quot;开发语言&quot;">​</a></h3><ul><li><strong>ArkTS</strong>：HarmonyOS 推荐的开发语言，基于 TypeScript 扩展</li><li><strong>JavaScript</strong>：支持传统的 JS 开发方式</li><li><strong>eTS</strong>：增强型 TypeScript，是 ArkTS 的前身</li></ul><h3 id="开发框架" tabindex="-1">开发框架 <a class="header-anchor" href="#开发框架" aria-label="Permalink to &quot;开发框架&quot;">​</a></h3><ul><li><strong>ArkUI</strong>：HarmonyOS 推荐的应用开发框架，提供声明式和类 Web 两种开发范式</li><li><strong>声明式开发范式</strong>：基于 ArkTS 的声明式 UI 开发，类似 React、Vue 的开发方式</li><li><strong>类 Web 开发范式</strong>：基于 HTML、CSS、JavaScript 的开发方式</li></ul><h2 id="开发流程" tabindex="-1">开发流程 <a class="header-anchor" href="#开发流程" aria-label="Permalink to &quot;开发流程&quot;">​</a></h2><p>HarmonyOS 应用开发的基本流程：</p><ol><li><strong>环境搭建</strong>：安装 DevEco Studio 和 HarmonyOS SDK</li><li><strong>项目创建</strong>：使用 DevEco Studio 创建 HarmonyOS 项目</li><li><strong>应用开发</strong>：使用 ArkTS/JavaScript 和 ArkUI 框架开发应用</li><li><strong>应用调试</strong>：在模拟器或真机上调试应用</li><li><strong>应用签名</strong>：生成应用签名文件</li><li><strong>应用打包</strong>：打包生成 HAP（HarmonyOS Ability Package）文件</li><li><strong>应用发布</strong>：发布到 HarmonyOS 应用市场</li></ol><h2 id="社区支持" tabindex="-1">社区支持 <a class="header-anchor" href="#社区支持" aria-label="Permalink to &quot;社区支持&quot;">​</a></h2><p>HarmonyOS 拥有活跃的开发者社区和丰富的学习资源：</p><ul><li><a href="https://developer.harmonyos.com/cn/docs/documentation/doc-guides/introduction-0000001053582387" target="_blank" rel="noreferrer">HarmonyOS 官方文档</a></li><li><a href="https://developer.harmonyos.com/cn/develop" target="_blank" rel="noreferrer">HarmonyOS 开发者社区</a></li><li><a href="https://developer.harmonyos.com/cn/docs/documentation/doc-references/arkui-overview-0000001156633554" target="_blank" rel="noreferrer">方舟开发框架（ArkUI）文档</a></li><li><a href="https://developer.harmonyos.com/cn/training" target="_blank" rel="noreferrer">HarmonyOS 开发者学院</a></li></ul><h2 id="版本更新" tabindex="-1">版本更新 <a class="header-anchor" href="#版本更新" aria-label="Permalink to &quot;版本更新&quot;">​</a></h2><p>HarmonyOS 不断迭代更新，引入新特性和改进：</p><ul><li><strong>HarmonyOS 2.0</strong>：首个面向消费者的版本，支持智能手机等设备</li><li><strong>HarmonyOS 3.0</strong>：增强了分布式能力，支持更多设备类型</li><li><strong>HarmonyOS 4.0</strong>：提升了性能和用户体验，引入更多智能功能</li></ul><p>HarmonyOS 正持续演进，为开发者提供更强大的工具和更丰富的功能，助力构建全场景智慧生活体验。</p>',24)]))}const u=a(e,[["render",l]]);export{m as __pageData,u as default};
